-- Source-verified tawasheeh expansion.
-- Every audio URL points to an Internet Archive item marked Public Domain on its source page.
-- Keep source_url and license in metadata so the UI and reviewers can audit provenance.

WITH categories AS (
  SELECT id, slug FROM public.tawasheeh_categories
  WHERE slug IN ('religious', 'prophetic', 'supplications')
), tracks (title_ar, title_en, slug, artist_ar, artist_en, category_slug, audio_url, duration, featured, metadata) AS (
