)
INSERT INTO public.tawasheeh (title_ar, title_en, slug, artist_ar, artist_en, category_id, audio_url, duration, featured, published, metadata)
SELECT t.title_ar, t.title_en, t.slug, t.artist_ar, t.artist_en, c.id, t.audio_url, t.duration, t.featured, true, t.metadata
FROM tracks t JOIN categories c ON c.slug = t.category_slug
ON CONFLICT (slug) DO UPDATE SET audio_url = EXCLUDED.audio_url, duration = EXCLUDED.duration, featured = EXCLUDED.featured, published = true, metadata = EXCLUDED.metadata, updated_at = now();

-- Existing seed rows without a verified direct audio file remain unpublished
-- by the API until a source URL is reviewed and added in a later migration.
